<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\HasMany;
class GuiaInternaSincronizacion extends Model{protected $table='guias_internas_sincronizaciones';protected $fillable=['fecha_inicio','fecha_fin','estado','filtros','iniciado_por','proceso_pid','paginas_total','paginas_procesadas','cabeceras_guardadas','detalles_guardados','cabeceras_eliminadas','errores','mensaje_error','iniciado_en','completado_en'];protected function casts():array{return['fecha_inicio'=>'date','fecha_fin'=>'date','filtros'=>'array','iniciado_en'=>'datetime','completado_en'=>'datetime'];}public function guias():HasMany{return $this->hasMany(GuiaInterna::class,'sincronizacion_id');}}
